{
  "status": "SUPPORTED",
  "task_summary": "Identify parts, fasten them on a workbench, and return the tool.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_target",
        "entity_kind": "OBJECT",
        "function": "The object to be repaired or assembled.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["workpiece", "object"],
        "required_properties": ["needs fastening"]
      },
      {
        "id": "component",
        "entity_kind": "OBJECT",
        "function": "The part to be attached to the target.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["part", "piece"],
        "required_properties": ["compatible with target"]
      },
      {
        "id": "fastener",
        "entity_kind": "OBJECT",
        "function": "The connector used to secure the part.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screw", "bolt", "nut"],
        "required_properties": ["fits component"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "The implement used to apply the fastener.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["wrench", "screwdriver", "pliers"],
        "required_properties": ["applies fastener"]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "The surface where the task occurs and tools are placed.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "bench"],
        "required_properties": ["holds objects"]
      }
    ],
    "functional_relations": [
      {
        "id": "attachment",
        "relation": "component is attached to fastening_target",
        "participant_roles": ["component", "fastening_target"]
      ,
      "required": true
      },
      {
        "id": "securing",
        "relation": "fastener secures component to fastening_target",
        "participant_roles": ["fastener", "component", "fastening_target"]
      ,
      "required": true
      },
      {
        "id": "location",
        "relation": "fastening_target is located at workbench",
        "participant_roles": ["fastening_target", "workbench"]
      ,
      "required": false
      }
    ],
    "operation_pairings": [
      {
        "id": "identify_components",
        "operation": "Locate component and fastener in the scene",
        "participant_roles": ["component", "fastener", "workbench"]
      ,
      "operation_count": 1
      },
      {
        "id": "fasten_assembly",
        "operation": "Secure component to fastening_target using fastener and fastening_tool",
        "participant_roles": ["component", "fastening_target", "fastener", "fastening_tool"]
      ,
      "operation_count": 1
      },
      {
        "id": "place_tool",
        "operation": "Place fastening_tool on workbench",
        "participant_roles": ["fastening_tool", "workbench"]
      ,
      "operation_count": 1
      }
    ]
  }
,
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastening_target": [],
      "component": [
        { "label": "yellow_blue_object", "visual_description": "Item on tray on workbench" }
      ],
      "fastener": [],
      "fastening_tool": [],
      "workbench": [
        { "label": "wooden_table", "visual_description": "Table in center of room" }
      ]
    },
    "inspectable_regions": [
      {
        "id": "cabinet",
        "label": "blue_cabinet",
        "visual_description": "Closed blue cabinet behind workbench",
        "reason": "Likely contains fasteners or tools"
      },
      {
        "id": "drawers",
        "label": "desk_drawers",
        "visual_description": "Closed drawers under workbench",
        "reason": "Likely contains tools or small parts"
      },
      {
        "id": "tray",
        "label": "black_tray",
        "visual_description": "Tray on workbench surface",
        "reason": "Contains visible component-like object"
      }
    ],
    "inspection_order": ["cabinet", "drawers", "tray"]
  }
,
  "unsupported_reason": ""
,
  "schema_version": 3
}
